import { readFileSync, writeFileSync } from "node:fs";

const SOURCE = "assets/wordlists/eff_large_wordlist.txt";
const TARGET = "src-web/wordlist-eff.js";

const HEADER = `// SherLock passphrase wordlist
// Generated from the EFF Large Wordlist by tools/build_wordlist.mjs
// Source: https://www.eff.org/files/2016/07/18/eff_large_wordlist.txt
// Author: Electronic Frontier Foundation (EFF)
// License: CC BY 3.0 US (https://creativecommons.org/licenses/by/3.0/us/)
// Attribution required: "EFF Large Wordlist" by the Electronic Frontier Foundation.
// Do NOT edit this file by hand; regenerate with: node tools/build_wordlist.mjs
export const EFF_WORDLIST = Object.freeze([`;

const FOOTER = `]);
`;

function main() {
  const raw = readFileSync(SOURCE, "utf8");
  const lines = raw.split("\n");
  const words = [];
  let duplicates = 0;
  const seen = new Set();

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const parts = trimmed.split("\t");
    if (parts.length !== 2) {
      throw new Error(`Línia no vàtida al wordlist: ${JSON.stringify(line)}`);
    }
    const [index, word] = parts;
    if (!/^\d{5}$/.test(index)) {
      throw new Error(`Índex no vàlid: ${JSON.stringify(index)}`);
    }
    if (!/^[a-z-]+$/.test(word) || word.startsWith("-") || word.endsWith("-")) {
      throw new Error(`Paraula no vàlida: ${JSON.stringify(word)}`);
    }
    if (seen.has(word)) {
      duplicates += 1;
      continue;
    }
    seen.add(word);
    words.push(word);
  }

  if (words.length !== 7776) {
    throw new Error(`Esperaven-se 7776 paraules, s'han trobat ${words.length}`);
  }
  if (duplicates !== 0) {
    throw new Error(`Hi ha ${duplicates} duplicats al wordlist`);
  }

  const content = HEADER + words.map((w) => `  ${JSON.stringify(w)},`).join("\n") + "\n" + FOOTER;
  writeFileSync(TARGET, content, "utf8");
  console.log(`Generat ${TARGET} amb ${words.length} paraules (EFF Large Wordlist).`);
}

main();
